import subprocess, tempfile, os
def run(args):
    return subprocess.run(args, capture_output=True, text=True)

def test_seed(dim, seed, thread):
    with tempfile.TemporaryDirectory() as tmp:
        train=os.path.join(tmp,"train.txt")
        out=os.path.join(tmp,"out")
        with open(train,"w") as f:
            for i in range(1000):
                f.write("__label__1 This is a great movie with excellent acting and wonderful story .\n")
                f.write("__label__2 This is a terrible movie with bad acting and boring story .\n")
                f.write("__label__1 I loved this film it was fantastic and amazing .\n")
                f.write("__label__2 I hated this film it was horrible and awful .\n")
        res=run(["./executable","supervised","-input",train,"-output",out,"-dim",str(dim),"-thread",str(thread),"-seed",str(seed)])
        return res.returncode, res.stderr

for seed in [0,1,2,5,10,100]:
    code, err = test_seed(10, seed, 1)
    print(f"seed {seed} dim10 thread1 code {code} NaN {'NaN' in err}")
for seed in [0,1,2]:
    code, err = test_seed(80, seed, 1)
    print(f"seed {seed} dim80 thread1 code {code} NaN {'NaN' in err}")

for thr in [1,2,12]:
    code, err = test_seed(10, 0, thr)
    print(f"thr {thr} dim10 seed0 code {code} NaN {'NaN' in err}")

